/* Begin file src/rank_agreement.hpp */
#ifndef NAXP_RANK_AGREEMENT_HPP
#define NAXP_RANK_AGREEMENT_HPP

#include <cstdint>

namespace logmu::detail
{
	/// Whether two machines give the same encoded value to every string they both hold.
	enum class agreement
	{
		/// Every string both machines hold takes the same value under each.
		agrees,

		/// At least one string both hold takes different values.
		differs,

		/// Not decided. Either a count saturated, so the arithmetic is not the true rank, or
		/// the walk outgrew its budget.
		undecided,
	};

	/// Comparing the encoded values two canonical machines give the strings they share.
	///
	/// A value is a rank: the count of strings that precede this one. Walking a machine
	/// accumulates that count a character at a time, so walking two machines together and
	/// carrying the difference of the two running totals says whether they will end up
	/// agreeing.
	///
	/// The difference at a state pair is a property of the pair, not of the path that reached
	/// it. Two strings that arrive at the same pair with different differences have the same
	/// completions available to both machines from there, so whatever suffix takes one to an
	/// accepting pair takes the other as well, and the two cannot both come out at zero. A
	/// second, unequal arrival is therefore a disagreement rather than something to explore,
	/// which is what keeps this linear in the size of the product rather than exponential in
	/// the alphabet.
	namespace rank_agreement
	{
		/// How many state pairs the walk may visit before giving up.
		///
		/// W6 caps each machine at 2000 states, so a product can in principle reach four
		/// million pairs. This is far below that, because a comparison worth making is between
		/// two naxps that resemble one another, and one that explodes is telling you they do
		/// not.
		inline constexpr int max_pairs = 200'000;

		/// Whether `a` and `b` give the same value to every string they both hold.
		///
		/// @param a The first canonical machine.
		/// @param b The second canonical machine.
		/// @param budget How many state pairs to allow.
		agreement compare(const state_map& a, const state_map& b, int budget = rank_agreement::max_pairs);

		/// What taking one character adds to the running total, which is the count of strings
		/// the machine passes over to reach it.
		///
		/// The same arithmetic as `codec::encode`, and it has to stay the same: the transitions
		/// before the one taken are skipped whole, and within the one taken the character's own
		/// position counts once for each string its successor holds.
		///
		/// @param from The state the character is read in.
		/// @param taken The transition the character belongs to.
		/// @param c The character.
		std::uint64_t contribution(const state& from, const transition& taken, char c) noexcept;
	}
}

#endif
/* End file src/rank_agreement.hpp */

#include <optional>
#include <string>

namespace logmu::detail
{
	/// Whether two naxps give the same encoded value to every string they both accept.
	///
	/// This is the question the encoding relation turns on, and it is not the question of
	/// whether the two canonicalise alike. `(A|B)!A` and `(A|B)!B` print different things for
	/// `B` and give it the same value, because each rank is taken in its own canonical language.
	/// So canonical forms are never compared here. Each side's output is fed into its own
	/// canonical machine as it is emitted, and what is carried is the difference of the two
	/// running rank totals, as the rank agreement carries it over two machines.
	///
	/// A state is a pair of transduction residuals, one from each naxp, with the state each
	/// canonical machine has reached on its side's output so far. Nothing is held back: a copied
	/// character is fixed by narrowing the block to single characters before it is walked, a
	/// rendering is a fixed string, and a skipped element's end of text output is a fixed
	/// string, so every emission is concrete at the step that makes it. That is why there is no
	/// delay here where the W3 checker needs one. The square compares two strings that arrive
	/// at different times; this compares two numbers, and a number can be accumulated as its
	/// string arrives.
	///
	/// The difference at a state is a property of the state, not of the path: from a state
	/// every completion both sides accept has one output per side, by W3, so the rank each side
	/// adds over it is fixed, and two arrivals with different differences cannot both finish at
	/// zero. A second and unequal arrival is therefore a disagreement rather than a branch, with
	/// one proviso that the rank agreement also makes: it counts only where the two residuals
	/// still share a completion.
	///
	/// The argument, the pairs it was tried on and the construction it replaces are in
	/// `encoding/comparison-square-review.md`.
	namespace value_agreement
	{
		/// How many product states the walk may build before giving up.
		///
		/// The same figure as `rank_agreement::max_pairs`, for the same reason.
		inline constexpr int max_tuples = 200'000;

		/// Whether `a` and `b` give the same value to every string both accept.
		///
		/// @param a The first naxp.
		/// @param b The second naxp.
		/// @param witness Where they differ, a string both accept and value differently, the
		///     shortest the walk found. Otherwise nothing.
		/// @param budget How many product states to allow.
		/// @returns Whether they agree, differ, or could not be decided within the budget.
		agreement compare(const compilation& a, const compilation& b, std::optional<std::string>& witness, int budget = value_agreement::max_tuples);
	}
}

#endif
/* End file src/value_agreement.hpp */

#include <cstdint>

/// How the languages of two machines, and the encodings of two naxps, stand to one another.
///
/// States are interned within one build, so two languages built through the same factory are
/// equal exactly when their start states are the same object. Two naxps parsed separately do
/// not share a factory, so that shortcut is unavailable here and the walks below are what
/// decide it.
namespace logmu::detail::relations
{
	/// How the language of `a` stands to the language of `b`.
	///
	/// A walk of the product, carrying two facts: whether `a` holds a string `b` does not, and
	/// whether the reverse holds. Both machines are acyclic and trimmed, so a state reached with
	/// characters the other side cannot take is a witness on its own and needs no completion.
	///
	/// @returns The relationship, from `a`'s point of view.
	set_relationship compare_languages(const state_map& a, const state_map& b);

	/// How the encoding of `a` stands to the encoding of `b`, each taken as the set of (text,
	/// value) pairs it defines.
	///
	/// One graph contains another exactly when its domain does and the two functions agree on
	/// the smaller domain. So the relationship is the one between the accepted languages,
	/// provided every string both accept takes the same value under each, and `incomparable`
	/// otherwise, since a string valued differently puts a pair in each graph that the other
	/// lacks.
	///
	/// Value agreement is asked of the values and never of the canonical forms. `(A|B)!A` and
	/// `(A|B)!B` print `B` differently and value it alike, and their encodings are equal. Where
	/// neither naxp holds a unified element the canonical machines are the accepted ones and
	/// the rank agreement decides exactly. Otherwise its disagreement is still exact, because a
	/// shared canonical string is fixed by both canonicalisations, and it is tried first for
	/// that reason; its agreement says nothing about the strings a unified element rewrites,
	/// which the value agreement then decides over parses.
	///
	/// This is the one axis of the comparison that can fail to be decided, when a walk outgrows
	/// its budget. It then returns false and the relationship is left as `incomparable`, which
	/// is the value that claims nothing.
	///
	/// @param relationship The relationship, from `a`'s point of view.
	/// @param budget How many product states either walk may build.
	/// @returns Whether the relationship was decided.
	bool try_compare_encodings(const compilation& a, const compilation& b, set_relationship& relationship, int budget = value_agreement::max_tuples);

	/// The lowest value both machines hold that they decode to different strings, or zero
	/// where every value both hold decodes alike.
	///
	/// The walk enumerates both canonical languages in the order the specification defines,
	/// the empty string first and then each first class in set order, each character of it in
	/// ASCII order and each continuation in turn, and compares the two enumerations position
	/// by position. Where two continuations are reached by the same character the comparison
	/// recurses and a whole chunk is stepped over by its count, which is what keeps the walk
	/// linear in the product of the machines rather than in the number of values. The result
	/// at a pair of states does not depend on how the pair was reached, so it is memoised.
	///
	/// Counts are trusted, which W5 guarantees for a canonical machine: the count of values is
	/// capped at 2^64 - 1, so no count here is saturated.
	///
	/// @param a The first canonical machine.
	/// @param b The second canonical machine.
	/// @returns The value, or zero for none.
	std::uint64_t first_divergent_value(const state_map& a, const state_map& b);
}

